import{_ as r,C as a,c as i,o as s,a3 as n,G as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Credit notes and refunds","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/credit-notes-and-refunds.md","filePath":"master/finance/customer-invoices/credit-notes-and-refunds.md","lastUpdated":1791902625000}'),d={name:"master/finance/customer-invoices/credit-notes-and-refunds.md"};function l(c,e,h,u,g,m){const t=a("ImagePopup");return s(),i("div",null,[e[0]||(e[0]=n('<h1 id="credit-notes-and-refunds" tabindex="-1">Credit notes and refunds <a class="header-anchor" href="#credit-notes-and-refunds" aria-label="Permalink to &quot;Credit notes and refunds&quot;">​</a></h1><p>A credit note and a refund are the same idea on two sides. A customer <strong>credit note</strong> reduces what a customer owes you. A vendor <strong>refund</strong> reduces what you owe a supplier. A posted invoice or bill cannot be edited, so these documents are the correct way to fix it.</p><blockquote><p><strong>In simple words:</strong> A credit note or refund is a &quot;negative invoice&quot;. It says that part or all of an earlier document no longer counts.</p></blockquote><h2 id="why-you-issue-one" tabindex="-1">Why you issue one <a class="header-anchor" href="#why-you-issue-one" aria-label="Permalink to &quot;Why you issue one&quot;">​</a></h2><ul><li>Goods or services come back.</li><li>You charged the wrong price or quantity.</li><li>You must cancel a posted invoice or bill.</li><li>You give a goodwill discount after the sale.</li></ul><h2 id="credit-note-or-refund" tabindex="-1">Credit note or refund? <a class="header-anchor" href="#credit-note-or-refund" aria-label="Permalink to &quot;Credit note or refund?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Customer side</th><th>Vendor side</th></tr></thead><tbody><tr><td>Document</td><td>Credit note</td><td>Refund</td></tr><tr><td>Original</td><td>Customer invoice</td><td>Vendor bill</td></tr><tr><td>Button</td><td><strong>Credit Note</strong></td><td><strong>Refund</strong></td></tr><tr><td>Invoices app</td><td><code>Invoices → Customers → Credit Notes</code></td><td><code>Invoices → Vendors → Refunds</code></td></tr><tr><td>Accounting app</td><td><code>Accounting → Customers → Credit Notes</code></td><td><code>Accounting → Vendors → Refunds</code></td></tr></tbody></table><p>Both apps show the same screens. Both lists have the views <strong>Default</strong>, <strong>Draft</strong>, <strong>Posted</strong>, <strong>Cancelled</strong> and <strong>Not Secured</strong>. The columns match the invoice and bill lists, including <strong>Total</strong>, <strong>Amount Due</strong> and <strong>Payment State</strong>. See <a href="./create-invoice.html">Create an invoice</a> and <a href="./../vendor-bills/create-bill.html">Create a vendor bill</a>.</p>',8)),o(t,{src:"/images1/finance/credit_note_list.png",alt:"Credit Notes list with the view tabs and one draft credit note for Azure Interiors"}),o(t,{src:"/images1/finance/refund_list.png",alt:"Refunds list with the view tabs and one draft refund for FreshFoods Wholesale"}),e[1]||(e[1]=n('<h2 id="way-1-from-a-posted-invoice-or-bill-recommended" tabindex="-1">Way 1: from a posted invoice or bill (recommended) <a class="header-anchor" href="#way-1-from-a-posted-invoice-or-bill-recommended" aria-label="Permalink to &quot;Way 1: from a posted invoice or bill (recommended)&quot;">​</a></h2><p>Use this way to correct an existing document. The new document is linked to the original, so Aureus can settle the two against each other.</p><ol><li>Open the posted document. For example, open invoice <strong>INV/2026/1</strong> of Azure Interiors, or bill <strong>BILL/2026/4</strong> of FreshFoods Wholesale.</li><li>Click <strong>Credit Note</strong> on an invoice, or <strong>Refund</strong> on a bill.</li><li>Fill in the window: <ul><li><strong><em>Reason displayed on Reverse:</em></strong> Why you issue it. Required. For example &quot;Customer returned 2 Camping Hammocks&quot;. It can have up to 245 characters.</li><li><strong><em>Journal:</em></strong> It starts as the journal of the original. Only that journal is offered.</li><li><strong><em>Date:</em></strong> It starts as today.</li></ul></li><li>Submit the window.</li></ol><p>Aureus creates a <strong>Draft</strong> and opens it. The reference of the draft starts with &quot;Reversal of:&quot; and the original number.</p>',4)),o(t,{src:"/images1/finance/credit_note_button_modal.png",alt:"Create Credit Note window on INV/2026/1 with Reason, Journal and Date filled in"}),o(t,{src:"/images1/finance/bill_refund_modal.png",alt:"Create Refund window on BILL/2026/4 with Reason, Journal and Date filled in"}),e[2]||(e[2]=n('<h3 id="what-the-draft-contains" tabindex="-1">What the draft contains <a class="header-anchor" href="#what-the-draft-contains" aria-label="Permalink to &quot;What the draft contains&quot;">​</a></h3><p>The draft copies the lines of the original. Each line keeps its product, quantity, taxes and price. For example, the credit note for INV/2026/1 shows the same lines with a total of 1,050.00 before tax. The refund for BILL/2026/4 shows 29,600.00 before tax.</p><h3 id="edit-the-draft-for-a-partial-credit" tabindex="-1">Edit the draft for a partial credit <a class="header-anchor" href="#edit-the-draft-for-a-partial-credit" aria-label="Permalink to &quot;Edit the draft for a partial credit&quot;">​</a></h3><p>To credit everything, change nothing. To credit part of the document:</p><ol><li>Open the draft and click <strong>Edit</strong>.</li><li>Lower the <strong>Quantity</strong> of a line, or delete the lines you do not credit.</li><li>Click <strong>Save changes</strong> and check the <strong>Total</strong>.</li></ol><h2 id="way-2-manually-from-the-list" tabindex="-1">Way 2: manually from the list <a class="header-anchor" href="#way-2-manually-from-the-list" aria-label="Permalink to &quot;Way 2: manually from the list&quot;">​</a></h2><p>Use this way when there is no original to link, such as a goodwill credit or a credit note sent by a supplier.</p><ol><li>Go to the Credit Notes or Refunds list.</li><li>Click <strong>New Credit Note</strong> or <strong>New Refund</strong>.</li><li>Fill in the form like an invoice or a bill: customer or vendor, dates, <strong>Journal</strong>, <strong>Currency</strong> and the <strong>Invoice Lines</strong>. For a refund, keep the supplier&#39;s credit note number in <strong>Bill Reference</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',8)),o(t,{src:"/images1/finance/credit_note_create.png",alt:"New Credit Note form with Customer Azure Interiors and one product line"}),o(t,{src:"/images1/finance/refund_create.png",alt:"New Refund form for FreshFoods Wholesale with one product line"}),e[3]||(e[3]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>A manual document is not linked to an original. To use it against an invoice, open a posted invoice of the same customer. An outstanding credit shows under the totals with an <strong>Add</strong> button. Click <strong>Add</strong> to apply it. Click <strong>Unlink</strong> to undo.</p></div><h2 id="confirm-it" tabindex="-1">Confirm it <a class="header-anchor" href="#confirm-it" aria-label="Permalink to &quot;Confirm it&quot;">​</a></h2><ol><li>Open the draft and check the lines and the <strong>Total</strong>.</li><li>Click <strong>Confirm</strong>. The state becomes <strong>Posted</strong>.</li></ol><p>When the document was created from a posted invoice or bill, Aureus matches it against the original on confirm. The <strong>Amount Due</strong> of the original falls by the amount of the credit note or refund. A full credit leaves nothing to pay.</p><p><strong>Example:</strong> Invoice INV/2026/1 is $1,207.50 and not paid. You issue a credit note for the full amount and confirm it. The invoice has nothing left to pay.</p><p>If money must move, use <strong>Pay</strong> on the credit note or refund. See <a href="./../payments/register-payment.html">Register a payment</a>.</p><h2 id="statuses-and-buttons" tabindex="-1">Statuses and buttons <a class="header-anchor" href="#statuses-and-buttons" aria-label="Permalink to &quot;Statuses and buttons&quot;">​</a></h2><p>A credit note or refund has the same states as an invoice.</p><ul><li><strong>Draft:</strong> You are still editing. Nothing is recorded in your accounts.</li><li><strong>Posted:</strong> You confirmed it. It now counts in your accounts.</li><li><strong>Cancelled:</strong> You cancelled the draft.</li></ul><p>It also has a <strong>Payment State</strong>, such as <strong>Not paid</strong>, <strong>Paid</strong> or <strong>Reversed</strong>.</p><p>Buttons:</p><ul><li><strong>Confirm:</strong> Posts a draft.</li><li><strong>Cancel:</strong> Cancels a draft.</li><li><strong>Delete:</strong> Removes a draft. A posted document cannot be deleted.</li><li><strong>Pay:</strong> Records a payment on a posted document.</li><li><strong>Preview:</strong> Shows the printable document.</li><li><strong>Print &amp; Send:</strong> Emails a credit note to the customer.</li><li><strong>Set as Checked:</strong> Marks a posted refund as reviewed.</li><li><strong>Reset To Draft:</strong> Moves a posted or cancelled document back to draft. Linked payments are unlinked.</li></ul><p>The <strong>Credit Note</strong> and <strong>Refund</strong> buttons do not appear on a credit note or refund itself.</p><h2 id="numbering" tabindex="-1">Numbering <a class="header-anchor" href="#numbering" aria-label="Permalink to &quot;Numbering&quot;">​</a></h2><p>When the journal has <strong>Dedicated Credit Note Sequence</strong> turned on, the number starts with <strong>R</strong>. A credit note in the INV journal is <code>RINV/2026/00004</code>. A refund in the BILL journal is <code>RBILL/2026/00005</code>. The number appears when the draft is created. See <a href="./invoice-sequence.html">Invoice sequence</a>.</p><h2 id="what-happens-in-the-accounts" tabindex="-1">What happens in the accounts <a class="header-anchor" href="#what-happens-in-the-accounts" aria-label="Permalink to &quot;What happens in the accounts&quot;">​</a></h2><p>A credit note posts the opposite of the invoice. Take INV/2026/1 for Azure Interiors.</p><ul><li>The invoice raised the customer balance and credited income and tax.</li><li>The credit note lowers the customer balance and debits income and tax.</li></ul><p>A refund does the same on the vendor side. For BILL/2026/4, the refund lowers what you owe FreshFoods Wholesale and reduces the expense and tax. Open the <strong>Journal Items</strong> tab of the document to see the lines. See <a href="./../accounting-entries/journal-entries.html">Journal entries</a>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Always write a clear <strong>Reason</strong>. It helps your accountant and the other party.</li><li>To fix a small mistake, credit the whole document, then create a new correct one.</li><li>Avoid <strong>Reset To Draft</strong> on a posted invoice the customer already received. A credit note leaves a clear trail.</li><li>Credit before you pay when possible. It keeps the <strong>Amount Due</strong> simple.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Invoicing processes</a></li><li><a href="./create-invoice.html">Create an invoice</a></li><li><a href="./../vendor-bills/create-bill.html">Create a vendor bill</a></li><li><a href="./invoice-sequence.html">Invoice sequence</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li></ul>',23))])}const b=r(d,[["render",l]]);export{p as __pageData,b as default};
